			const viewportRect = this._getViewportRect();
			let configuredPosition = this.position;
			let domRootRect = null;
			let visibleDomRootRect = null;
			if (!this._getDomRootElement()) configuredPosition = DialogViewPosition.SCREEN_CENTER;
			else ({domRootRect, visibleDomRootRect} = this._getDomRootRects(viewportRect));
