		const selectionPosition = selection.getFirstPosition();
		if (!selectionPosition) return null;
		let parent = selectionPosition.parent;
		while (parent) {
			if (parent.is("element") && isTableWidget(parent)) return parent;
			parent = parent.parent;
		}
		return null;
